<tr data-row-id="{{ $a->id }}" data-search="{{ mb_strtolower($a->patient->full_name.' '.$a->patient->dni.' '.$a->type->service->name.' '.$a->type->name) }}" data-service="{{ $a->type->service_id }}" data-status="{{ $a->status }}"><td><strong>{{ $a->scheduled_at->format('H:i') }}</strong></td><td><strong>{{ $a->patient->full_name }}</strong><small>DNI {{ $a->patient->dni }}</small></td><td>{{ $a->type->service->name }}</td><td>{{ $a->type->name }}</td><td><span class="status {{ $a->status }}">{{ ucfirst(str_replace('_',' ',$a->status)) }}</span></td><td>@if($a->status==='programada')<form id="confirmForm{{ $a->id }}" method="POST" action="{{ route('appointments.confirm',$a) }}" class="ajax-form" data-list-container="#patientsTableBody">@csrf @method('PUT')</form><form id="noshowForm{{ $a->id }}" method="POST" action="{{ route('appointments.no_show',$a) }}" class="ajax-form" data-list-container="#patientsTableBody">@csrf @method('PUT')</form><div class="row-actions"><button type="button" class="confirm-small" data-attendance-action="asistio" data-form-target="confirmForm{{ $a->id }}" data-patient-name="{{ $a->patient->full_name }}" data-patient-meta="{{ $a->scheduled_at->format('H:i') }} · {{ $a->type->service->name }}">Confirmar llegada</button><button type="button" class="noshow-small" data-attendance-action="no-asistio" data-form-target="noshowForm{{ $a->id }}" data-patient-name="{{ $a->patient->full_name }}" data-patient-meta="{{ $a->scheduled_at->format('H:i') }} · {{ $a->type->service->name }}">No asistió</button></div>@else<span class="confirmed-label">✓ Verificada</span>@endif</td></tr>
